# Check key cell type markers across clusters
import numpy as np
from scipy import sparse

# Glioblastoma-relevant markers
markers = {
    'Neuronal': ['SYT1', 'SNCG', 'NEFL', 'RBFOX3'],
    'Astrocyte': ['GFAP', 'ALB', 'SLC1A2', 'AQP4'],
    'Oligodendrocyte': ['OLIG2', 'MBP', 'PLP1', 'MOG'],
    'Endothelial': ['PECAM1', 'CDH5', 'VWF', 'CLDN5'],
    'Microglia': ['AIF1', 'TMEM119', 'P2RY12', 'CSF1R'],
    'T_cell': ['CD3D', 'CD3E', 'CD8A', 'CD4'],
    'Macrophage': ['CD163', 'CD68', 'MS4A6A'],
    'Stress': ['FOS', 'JUN', 'HSPA1A', 'HSP90AA1'],
    'Proliferation': ['MKI67', 'TOP2A', 'PCNA', 'MCM5']
}

print("=== Marker Expression by Cluster (mean normalized) ===\n")
for celltype, genes in markers.items():
    expr_vals = {}
    for cluster in ['0', '3', '12', '18']:
        mask = adata.obs['leiden'] == cluster
        vals = []
        for gene in genes:
            if gene in adata.var_names:
                if sparse.issparse(adata[mask].X):
                    vals.append(adata[mask].X.mean())
                else:
                    vals.append(np.mean(adata[mask].X))
            else:
                vals.append(0)
        expr_vals[cluster] = np.mean(vals) if vals else 0

    print(f"{celltype:15s}: ", end="")
    for cluster in ['0', '3', '12', '18']:
        print(f"C{cluster}:{expr_vals[cluster]:.3f}  ", end="")
    print()

# Check specific marker genes more directly
import numpy as np

# Key genes to check
genes_to_check = ['AIF1', 'CD163', 'GFAP', 'OLIG2', 'PECAM1', 'CD3D', 'CD8A', 'HBB', 'FOS', 'JUN', 'CD52', 'TMEM119', 'CD68', 'P2RY12']

print("=== Gene Expression by Cluster ===\n")
for gene in genes_to_check:
    if gene in adata.var_names:
        print(f"{gene:12s}: ", end="")
        for cluster in ['0', '3', '12', '18']:
            mask = adata.obs['leiden'] == cluster
            if hasattr(adata[mask].X, 'mean'):
                expr = float(adata[mask].X.mean())
            else:
                expr = float(np.mean(adata[mask].X))
            print(f"C{cluster}:{expr:.3f}  ", end="")
        print()
    else:
        print(f"{gene:12s}: NOT FOUND")
